def encrypt(text, shift=1):
    return ''.join(chr(ord(c)+shift) for c in text)

def reverse(text, enabled=True):
    if not enabled:
        return text
    return text[::-1]

def rotate(text, amount=1):
    return text[amount:] + text[:amount]

def replace(text, enabled=True):
    if not enabled:
        return text
    return text.replace('E','3').replace('I','1')

def lowercase(text):
    return text.lower()

